kubectl patch deployment web-app --type='json' -p='[
  {"op": "replace", "path": "/spec/strategy/rollingUpdate/maxSurge", "value": 1},
  {"op": "replace", "path": "/spec/strategy/rollingUpdate/maxUnavailable", "value": 0}
]'

kubectl set image deployment/web-app nginx=nginx:1.24-alpine
kubectl rollout status deployment/web-app -w
